-- Model: lnk_candidate_company__candidate_hkey_curr
-- Description: Current active relationship for LNK_CANDIDATE_COMPANY using ROW_NUMBER()
-- Generated by: bv pipeline generate transform
-- Link Type: RELATIONSHIP_BASED_LINK

WITH RANKED_RELATIONSHIPS AS (
SELECT
    l.LNK_CANDIDATE_COMPANY_HKEY AS LNK_CANDIDATE_COMPANY_HKEY,
    l.CANDIDATE_HKEY AS CANDIDATE_HKEY,
    l.COMPANY_HKEY AS COMPANY_HKEY,

    -- TODO: use generated tag instead of well-known name _CURRENT_ACTIVE_TIMESTAMP
    ls._CURRENT_ACTIVE_TIMESTAMP AS _CURRENT_RELATIONSHIP_TIMESTAMP, -- was ls._AIRBYTE_EXTRACTED_AT

    ROW_NUMBER() OVER (
        PARTITION BY l.CANDIDATE_HKEY -- parent hub hk
        ORDER BY ls._CURRENT_ACTIVE_TIMESTAMP DESC -- TODO: as above. Was ls._AIRBYTE_EXTRACTED_AT
    ) AS row_num

FROM {{ source('eli_dv_rv', 'lnk_candidate_company') }} l
INNER JOIN {{ ref('lks_ssc_candidate_company_curr') }} ls
    ON l.LNK_CANDIDATE_COMPANY_HKEY = ls.LNK_CANDIDATE_COMPANY_HKEY
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RELATIONSHIPS
WHERE row_num = 1
